const visual = {
  prepare: function (input) {
    var texts = ['0', '0.25', '0.5', '0.75', '1'];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = 60;
    var x1 = W - 60;
    var y = Math.round(H * 0.5);
    var ax = visualSdk.axis({ x0: x0, y0: y, x1: x1, y1: y, ticks: 5, tickLength: 10 });
    var paths = [{ id: 'axis', commands: ax }];
    var children = [{ type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2, cap: 'round' } }];
    for (var i = 0; i < 5; i++) {
      var lx = x0 + (x1 - x0) * i / 4;
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: lx, y: y + 18 },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'axis-0-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
